IF
Combined((ITEM)S_SHA_BookPlaque_906234ec-0dbb-48dc-ae60-74d27e6b07cc, _Book, _, _, _, _, _Item)
AND
NOT DB_GlobalFlag(SHA_SilentLibrary_State_SecretDoorOpened_2c300a57-0b71-4dc5-9a4f-7290cad0c9bc)
AND
_Book != S_SHA_SilentLibrary_SharranBook_005_40036615-8ed4-45cd-b554-4403bb1f6834
AND
QRY_OnlyOnce("SHA_SilentLibrary_TrapActivated")
THEN
ObjectTimerLaunch(_Item, "SHA_SilentLibrary_BookRemoval", 500);
PROC_SHA_SilentLibrary_MoveBook((ITEM)_Book, 0);
SetEntityEvent((ITEM)S_SHA_BookPlaque_906234ec-0dbb-48dc-ae60-74d27e6b07cc, "SHA_SilentLibrary_TriggerPedestalTrap");
TimerLaunch("SHA_SilentLibrary_TrapTimer", 12000);

